# /// script
# requires-python = ">=3.11"
# dependencies = ["mcp==2.3.0"]
# ///
"""Example MCP server whose tool schemas are generated by the official Python SDK (Pydantic v2).

It exists to capture *real generator output* (Optional -> anyOf+null, Literal -> enum, nested models ->
$defs/$ref, Field constraints, dict -> additionalProperties) for the corpus. Licensed Apache-2.0.
"""

from __future__ import annotations

from enum import Enum
from typing import Annotated, Literal

from mcp.server.mcpserver import MCPServer
from pydantic import BaseModel, Field

server = MCPServer("pydantic-example")


class Priority(str, Enum):
    low = "low"
    high = "high"


class Address(BaseModel):
    street: str
    city: str
    postcode: Annotated[str, Field(pattern=r"^[0-9]{5}$")]
    country: str = "US"


class Contact(BaseModel):
    name: Annotated[str, Field(min_length=1, max_length=80, description="Full name")]
    email: Annotated[str | None, Field(description="Email address")] = None
    age: Annotated[int | None, Field(ge=0, lt=150)] = None
    tags: list[str] = []
    address: Address | None = None


class TreeNode(BaseModel):
    label: str
    children: list[TreeNode] = []


@server.tool()
def create_contact(contact: Contact, priority: Priority = Priority.low, notify: bool = False) -> str:
    """Create a CRM contact."""
    return "ok"


@server.tool()
def search(
    query: Annotated[str, Field(min_length=1)],
    limit: Annotated[int, Field(ge=1, le=100)] = 10,
    sort: Literal["relevance", "date"] = "relevance",
    filters: dict[str, str] | None = None,
) -> str:
    """Search records."""
    return "ok"


@server.tool()
def save_tree(root: TreeNode, ratio: Annotated[float, Field(gt=0, multiple_of=0.5)] = 1.0) -> str:
    """Store a recursive tree."""
    return "ok"


@server.tool()
def schedule(when: Annotated[str, Field(json_schema_extra={"format": "date-time"})], ids: list[int] | int) -> str:
    """Schedule items at a time."""
    return "ok"


if __name__ == "__main__":
    server.run()
